var timeoutPolicy = Policy.TimeoutAsync<HttpResponseMessage>(
    TimeSpan.FromSeconds(5),
    TimeoutStrategy.Pessimistic);

var retryPolicy = Policy<HttpResponseMessage>
    .Handle<TimeoutRejectedException>()
    .OrResult(r => (int)r.StatusCode == 503)
    .WaitAndRetryAsync(3, retryAttempt =>
        TimeSpan.FromMilliseconds(200 * Math.Pow(2, retryAttempt)),
        onRetry: (outcome, timespan, retryNumber, context) =>
        {
            _logger.LogWarning(
                "Retry {Retry} for {Url} after {Ms}ms",
                retryNumber, context["url"], timespan.TotalMilliseconds);
            return Task.CompletedTask;
        });

var circuitBreaker = Policy<HttpResponseMessage>
    .Handle<HttpRequestException>()
    .CircuitBreakerAsync(2, TimeSpan.FromMinutes(1));
